mapper.select:
SELECT account_row.account_id AS ownedAccountId,
       COUNT(transaction_row.account_transaction_id) AS totalElements
FROM ACCOUNT account_row
         LEFT JOIN ACCOUNT_TRANSACTION transaction_row
                   ON transaction_row.account_id = account_row.account_id

                       AND transaction_row.tran_date >= #{startDate}


                       AND transaction_row.tran_date <= #{endDate}

WHERE account_row.account_id = #{accountId}
  AND account_row.user_id = #{userId}
  AND account_row.status = 'ACTIVE'
GROUP BY account_row.account_id

SELECT account_row.account_id AS ownedAccountId, transaction_row.account_transaction_id AS transactionId, transaction_row.transaction_category AS transactionCategory, transaction_row.tran_date AS transactionDate, transaction_row.tran_time AS transactionTime, transaction_row.out_amount AS outAmount, transaction_row.in_amount AS inAmount, transaction_row.loan_transaction_type_name AS loanTransactionTypeName, transaction_row.loan_principal_amount AS loanPrincipalAmount, transaction_row.loan_interest_amount AS loanInterestAmount, transaction_row.after_balance AS afterBalance, transaction_row.desc1, transaction_row.desc2, transaction_row.desc3, transaction_row.desc4 FROM ACCOUNT account_row INNER JOIN ACCOUNT_TRANSACTION transaction_row ON transaction_row.account_id = account_row.account_id WHERE account_row.account_id = #{accountId} AND account_row.user_id = #{userId} AND account_row.status = 'ACTIVE'
AND transaction_row.tran_date >= #{startDate}
AND transaction_row.tran_date <= #{endDate}
ORDER BY transaction_row.tran_date DESC, transaction_row.tran_time DESC, transaction_row.account_transaction_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.sql:
account_row.user_id = #{userId}
  AND account_row.status = 'ACTIVE'
  AND transaction_row.transaction_category = 'ORDINARY'
  AND transaction_row.out_amount > 0
  AND DATE_FORMAT(transaction_row.tran_date, '%Y-%m') = #{yearMonth}
